using System.Collections.Generic;
namespace RTMaquetaXR
{
    internal static partial class ModLocalization
    {
        static partial void AddRelease48(Dictionary<string,string> strings)
        {
            Add(strings, "Select and frame", "Seleccionar y encuadrar");
            Add(strings, "Right trigger: click / double-click", "Gatillo derecho: clic / doble clic");
            Add(strings, "Click selects. Double-click frames the actor or ship.", "Clic: seleccionar. Doble clic: encuadrar personaje o nave.");
            Add(strings, "A normal click never moves the camera. Double-click the same character or ship within 0.35 seconds to frame it at a moderate distance, facing its heading and relative to its actual height. A also clicks. On navigation maps, double-click retains its original function. UI clicks never reposition the camera.", "Un clic normal no mueve la cámara. Haz doble clic sobre el mismo personaje o nave en 0,35 segundos para encuadrarlo a distancia moderada, según su orientación y altura real. A también hace clic. En los mapas de navegación, el doble clic conserva su función original. Los clics en la interfaz no recolocan la cámara.");
            Add(strings, "First-person view", "Vista en primera persona");
            Add(strings, "Right trigger fully held: 2 s", "Gatillo derecho a fondo: 2 s");
            Add(strings, "Hold on a character or ship. B / zoom out leaves.", "Mantén sobre personaje o nave. B / alejar sale.");
            Add(strings, "Point at a character or ship and hold the right trigger at least 95% down for two seconds, without a grip. This enters its head view; the model is hidden from the VR eyes and heading changes are smoothed. Your physical head remains free. B or bringing both gripped hands together returns to the table. Deep holds never enter first person through a menu or navigation map.", "Señala un personaje o nave y mantén el gatillo derecho al menos al 95% durante dos segundos, sin grip. Entras en su vista en primera persona: el modelo se oculta para el visor y sus giros se suavizan. Tu cabeza sigue moviéndose libremente. B o juntar ambas manos con los grips pulsados devuelve la vista a la maqueta. Este gesto no entra en primera persona a través de menús ni mapas de navegación.");
            Add(strings, "Move in first person", "Mover en primera persona");
            Add(strings, "Right trigger fully held on ground: 2 s", "Gatillo derecho a fondo sobre suelo: 2 s");
            Add(strings, "Optional; on by default in exploration and ground combat.", "Opcional; activo por defecto en exploración y combate terrestre.");
            Add(strings, "Hold the right trigger at least 95% down for two seconds over a valid destination. Once the original game accepts the move, enter the selected actor head view and remain there during movement. No extra move or action-point cost is added. Invalid paths, ability targeting, enemy turns and deployment cannot enter head view. A short click moves normally. B cancels the current action; B or zooming out leaves head view.", "Mantén el gatillo derecho al menos al 95% durante dos segundos sobre un destino válido. Cuando el juego acepta el movimiento, entras en la vista del personaje seleccionado y permaneces en ella al moverte. No se añade otra orden ni coste de puntos. Rutas inválidas, apuntado de habilidades, turnos enemigos y despliegue no activan esta vista. Un clic breve mueve normalmente. B cancela la acción; B o alejar el zoom sale de primera persona.");
            Add(strings, "Exploration: move group. Maps: pan.", "Exploración: mover grupo. Mapas: desplazar.");
            Add(strings, "Move the selected group in On-foot exploration. Follow moving characters smoothly follows travel and aligns direction; off keeps the table still. Centre the stick to adopt the new heading. HUD hover does not stop movement; clicks and open menus do. On navigation maps, the right stick pans and left up/down zooms. Space combat keeps native pointer orders instead of stick piloting.", "Mueve el grupo seleccionado en Exploración a pie. Seguir personajes acompaña el movimiento y alinea la dirección con suavidad; desactivado mantiene la maqueta quieta. Centra el stick para adoptar la nueva dirección. Pasar por el HUD no detiene el movimiento; los clics y menús abiertos sí. En los mapas, el stick derecho desplaza y el izquierdo arriba/abajo acerca o aleja. Combate espacial conserva las órdenes con puntero.");
            Add(strings, "Rotate both servo-skulls or change their separation while holding both grips. Exploration zoom is limited by default; the main settings page can unlock it after a performance warning. Space combat has a much wider ship-relative zoom range, independent of the surface. Bringing hands together also leaves character or ship head view. Navigation maps use right-stick pan and left-stick zoom. Management panels use their own size settings.", "Gira ambos servocráneos o cambia su separación manteniendo los grips. El zoom de exploración está limitado por defecto; puedes liberarlo desde el menú principal tras un aviso de rendimiento. Combate espacial tiene un rango mucho más amplio, relativo a la nave e independiente del terrestre. Juntar las manos también sale de primera persona. Los mapas usan desplazamiento con stick derecho y zoom con izquierdo. Las pantallas de gestión tienen sus propios ajustes de tamaño.");
            Add(strings, "Live actions, weapon sets and attack variants.", "Acciones actuales, armas y variantes de ataque.");
            Add(strings, "Hold left grip and trigger. On the surface, left stick click switches Actions / Characters. Actions come from current equipment and skills. Switch weapon chooses a real equipment set; attacks with variants open another wheel of their native subtypes. Centre the stick before choosing from a changed wheel. Preview with the stick or right pointer; A or RIGHT trigger confirms. Space uses active ship weapons. B or releasing the opening controls cancels.", "Mantén grip y gatillo izquierdos. En tierra, clic del stick izquierdo alterna Acciones / Personajes. Las acciones proceden del equipo y habilidades actuales. Cambiar arma elige un conjunto real; los ataques con variantes abren otra rueda con sus subtipos originales. Centra el stick antes de elegir en una rueda que cambie. Stick o puntero derecho muestra la ficha; A o gatillo DERECHO confirma. En espacio aparecen armas de la nave activa. B o soltar la combinación cancela.");
            Add(strings, "Cancel / back", "Cancelar / volver");
            Add(strings, "B cancels the current order, wheel or window.", "B cancela la orden, rueda o ventana actual.");
            Add(strings, "B always cancels the current interaction: settings, wheel, native window or the game pending order. In gameplay it also leaves first-person view. The left menu button is Back/Cancel. Left trigger performs a secondary click. End turn always asks for a separate confirmation; pointing at or previewing an ability never ends the turn.", "B cancela la interacción actual: ajustes, rueda, ventana original u orden pendiente del juego. Durante la partida también sale de primera persona. El botón de menú izquierdo hace Volver/Cancelar. El gatillo izquierdo realiza clic secundario. Terminar turno siempre pide una confirmación aparte; señalar o consultar una habilidad nunca termina el turno.");
            Add(strings, "Right stick: pan · left stick up/down: zoom", "Stick derecho: desplazar · izquierdo arriba/abajo: zoom");
            Add(strings, "Independent size, position, content zoom and presets.", "Tamaño, posición, zoom del contenido y preajustes independientes.");
            Add(strings, "Galactic map and Star system map use their original routes, objects and travel confirmations. Centre both sticks after opening, then right stick pans and left up/down zooms. Point and click to select or travel; B returns. Under Advanced settings > Space, each map has its own size, distance, proportions, position, content zoom and saved layout. There is no group movement, selection rectangle or first-person view in navigation maps.", "Mapa estelar y Mapa galáctico usan sus rutas, objetos y confirmaciones de viaje originales. Centra ambos sticks al abrir: el derecho desplaza y el izquierdo arriba/abajo controla el zoom. Señala y pulsa para seleccionar o viajar; B vuelve. En Configuración avanzada > Espacio, cada mapa tiene tamaño, distancia, proporciones, posición, zoom del contenido y preajuste propios. No hay movimiento del grupo, selección rectangular ni primera persona en estos mapas.");
            Add(strings, "Click orders. Double-click frames. Deep hold: first person.", "Clic: orden. Doble clic: encuadrar. A fondo: primera persona.");
            Add(strings, "Use the same grip gestures and left-stick rotation/tilt, with a wider zoom range. Double-click a ship to frame its heading; hold the right trigger fully for two seconds to enter its view. Left wheel: weapons and their variants; right: ship-post abilities. Preview and confirm with A or the opposite trigger. Native units, resources and cooldowns govern availability. End turn always asks for confirmation. Original panels are visible by default, with an option to hide them.", "Usa los mismos gestos con grips y giro/inclinación con stick izquierdo, con un zoom más amplio. Doble clic sobre nave encuadra su orientación; gatillo derecho a fondo dos segundos entra en su vista. Rueda izquierda: armas y variantes; derecha: habilidades de puestos. Consulta y confirma con A o gatillo contrario. Unidades, recursos y recargas originales determinan la disponibilidad. Terminar turno siempre pide confirmación. Los paneles originales aparecen por defecto y pueden ocultarse.");
            Add(strings, "Select", "Seleccionar");
            Add(strings, "Order", "Orden");
            Add(strings, "Move group", "Mover grupo");
            Add(strings, "Rotate / tilt", "Girar / inclinar");
            Add(strings, "Wheels", "Ruedas");
            Add(strings, "Settings · four controls 2 s", "Ajustes · cuatro controles 2 s");
            Add(strings, "Leave first person", "Salir de primera persona");
            Add(strings, "Full hold 2 s · move in first person", "A fondo 2 s · mover en primera persona");
            Add(strings, "Scroll", "Desplazar");
            Add(strings, "Select / travel", "Seleccionar / viajar");
            Add(strings, "Pan / zoom", "Desplazar / zoom");
