            Add(strings, "Close map · L click also", "Cerrar mapa · también clic L");
            Add(strings, "Actor information", "Ficha de personaje");
            Add(strings, "Centre · keep information", "Centro · mantener ficha");
            Add(strings, "Click · switch mode", "Clic · cambiar modo");
            Add(strings, "Release · close", "Soltar · cerrar");
            Add(strings, "Point · ability info", "Señalar · ficha habilidad");
            Add(strings, "Use ability", "Usar habilidad");
            Add(strings, "Hold 1 s / click · select", "Mantener 1 s / clic · seleccionar");
            Add(strings, "Hold 1 s / click · open", "Mantener 1 s / clic · abrir");
            Add(strings, "Click controls", "Pulsar controles");
            Add(strings, "Navigate / adjust", "Navegar / ajustar");
            Add(strings, "Confirm / back", "Confirmar / volver");
            Add(strings, "Weapons / ship posts", "Armas / puestos");
            Add(strings, "Full right trigger 2 s on ground · move + head view", "Gatillo derecho a fondo 2 s sobre suelo · mover + primera persona");
            Add(strings, "Right stick · pan / left stick · zoom", "Stick derecho · desplazar / stick izquierdo · zoom");
            Add(strings, "All personal settings will be lost. Restore Performance and the approved defaults?", "Se perderán todos los ajustes personales. ¿Restablecer Rendimiento y los valores predefinidos aprobados?");
            Add(strings, "Changing advanced settings can misalign the interface or disrupt image quality, controls and performance.", "Modificar los ajustes avanzados puede desajustar la interfaz, la calidad de imagen, los controles y el rendimiento.");
            Add(strings, "Choose a complete render profile. Window placement and controls stay as configured. Custom restores your saved complete configuration. DLSS/DLAA use NVIDIA hardware; other GPUs use TAA.", "Elige un perfil completo de renderizado. Conserva la posición de ventanas y los controles. Personalizado recupera toda tu configuración guardada. DLSS/DLAA usa NVIDIA; las demás GPU usan TAA.");
            Add(strings, "Compare weapons", "Comparar armas");
            Add(strings, "Confirm", "Confirmar");
            Add(strings, "Continue to advanced settings", "Entrar en configuración avanzada");
            Add(strings, "Control hint placement", "Posición de ayudas de controles");
            Add(strings, "Custom configuration saved.", "Configuración personalizada guardada.");
            Add(strings, "Deep-trigger first-person movement", "Movimiento en primera persona con gatillo a fondo");
            Add(strings, "End the current character or ship turn?", "¿Terminar el turno del personaje o nave actual?");
            Add(strings, "End turn?", "¿Terminar turno?");
            Add(strings, "Free zoom can expose much more scenery and reduce performance. Remove the zoom limit?", "El zoom libre puede mostrar mucho más escenario y reducir el rendimiento. ¿Quitar el límite de zoom?");
            Add(strings, "Free zoom warning", "Aviso de zoom libre");
            Add(strings, "HUD preset", "Preajuste del HUD");
            Add(strings, "Hint height", "Altura de las ayudas");
            Add(strings, "Hint horizontal position", "Posición horizontal de ayudas");
            Add(strings, "Hint size", "Tamaño de las ayudas");
            Add(strings, "Hold the right trigger fully for two seconds on a valid destination to move in first person, in exploration or ground combat. Only an accepted native move enters head view. A short click moves normally.", "Mantén el gatillo derecho a fondo dos segundos sobre un destino válido para moverte en primera persona, en exploración o combate terrestre. Solo entra si el juego acepta la orden. Un clic breve mueve normalmente.");
            Add(strings, "In Management screens, point the right skull at a weapon in the inventory or equipment and press Y. The original game information window shows that weapon together with the equipped weapons eligible for comparison. Stats, bonuses and art remain native. Scroll with the right stick; B closes the information. This never equips, sells or discards an item.", "En Pantallas de gestión, señala con el servocráneo derecho un arma del inventario o equipo y pulsa Y. La ventana original muestra esa arma junto a las equipadas que el juego permite comparar. Estadísticas, bonificaciones y arte siguen siendo originales. Stick derecho desplaza; B cierra la ficha. Esto nunca equipa, vende ni descarta objetos.");
            Add(strings, "Limit exploration zoom", "Limitar zoom de exploración");
            Add(strings, "Map content zoom", "Zoom del contenido del mapa");
            Add(strings, "Map preset restored.", "Preajuste del mapa restaurado.");
            Add(strings, "Map preset saved.", "Preajuste del mapa guardado.");
            Add(strings, "Move the control hints down or up in your view.", "Baja o sube las ayudas de controles en tu campo de visión.");
            Add(strings, "Move the control hints left or right.", "Desplaza las ayudas de controles a izquierda o derecha.");
            Add(strings, "On keeps the predefined tabletop zoom range. Turning this off allows free zoom and can increase rendering cost.", "Activado conserva el rango de zoom predefinido. Desactivado permite zoom libre y puede aumentar el coste de renderizado.");
            Add(strings, "Open the original weapon comparisons together.", "Muestra juntas las fichas comparativas originales.");
            Add(strings, "Point at a weapon + Y", "Señalar un arma + Y");
            Add(strings, "Position and scale the transparent control reminders. These settings affect only the mod hints, including combat, and are saved with your configuration.", "Ajusta posición y tamaño de las ayudas transparentes. Solo afecta a los recordatorios del mod, incluidos los de combate, y se guarda con tu configuración.");
            Add(strings, "Quality preset", "Perfil de calidad");
            Add(strings, "Replace the saved layout for this map only.", "Sustituye únicamente el preajuste guardado de este mapa.");
            Add(strings, "Reset settings", "Restablecer ajustes");
            Add(strings, "Restore Performance and the approved default layout. Your personal configuration will be lost. Confirmation is required.", "Restaura Rendimiento y la disposición predefinida aprobada. Se perderá tu configuración personal. Requiere confirmación.");
            Add(strings, "Restore the saved layout for this map only.", "Recupera únicamente el preajuste guardado de este mapa.");
            Add(strings, "Save all current mod settings, including quality, panels, maps and controls. Replaces your previously saved Custom configuration.", "Guarda todos los ajustes actuales del mod: calidad, paneles, mapas y controles. Sustituye la configuración Personalizada guardada anteriormente.");
            Add(strings, "Save current as Custom", "Guardar actual como Personalizada");
            Add(strings, "Save or restore only this map's size, position, proportions, distance and content zoom. The other map and the rest of the interface are preserved.", "Guarda o recupera solo tamaño, posición, proporciones, distancia y zoom del contenido de este mapa. Conserva el otro mapa y el resto de la interfaz.");
            Add(strings, "Save your custom configuration first.", "Primero guarda tu configuración personalizada.");
            Add(strings, "Scale the icons and short labels together.", "Cambia a la vez el tamaño de los iconos y textos breves.");
            Add(strings, "Set the native camera zoom inside this map. Left stick up/down also changes it. This is independent of panel size and of the other map.", "Ajusta el zoom de la cámara original dentro de este mapa. Stick izquierdo arriba/abajo también lo modifica. Es independiente del tamaño del panel y del otro mapa.");
            Add(strings, "Show space combat panels", "Mostrar paneles del combate espacial");
            Add(strings, "Show the original ship panels. Visible by default during testing. Turning this off keeps opened windows and essential popups available; the wheels still operate.", "Muestra los paneles originales de la nave, visibles por defecto durante las pruebas. Al ocultarlos se conservan las ventanas abiertas y avisos esenciales; las ruedas siguen funcionando.");
            Add(strings, "Switch weapon", "Cambiar arma");
            Add(strings, "This map preset", "Preajuste de este mapa");
            Add(strings, "confirm", "confirmar");
            Add(strings, "Ultra performance", "Ultra rendimiento");
            Add(strings, "Maximum quality", "Máxima calidad");
            Add(strings, "Advanced settings warning", "Aviso de configuración avanzada");
            Add(strings, "WEAPON / ABILITY VARIANTS", "VARIANTES DE ARMA / HABILIDAD");
            Add(strings, "Y · compare pointed weapon", "Y · comparar arma señalada");
            Add(strings, "Compare weapon", "Comparar arma");
            Add(strings, "End-turn confirmation is unavailable.", "La confirmación de terminar turno no está disponible.");
        }
    }
}
